#include "looper_processor.h"
#include <iostream>
namespace{int checks=0;void check(bool value,const char* message){++checks;if(!value)throw std::runtime_error(message);}}
int main(){try{
    rocker::LoopBuffer buffer(8192);rocker::LooperProcessor loop;rocker::SampleClock clock;clock.prepare(8000,1);clock.tempo(120);loop.prepare(8000,1);rocker::LoopCommand install;install.buffer=&buffer;loop.command(install);rocker::LoopCommand first;first.kind=1;loop.command(first);loop.beginBlock();clock.beginBlock();
    for(int i=0;i<4000;++i)loop.process(i==100?.5:0,0,true,clock.tick());loop.endBlock();check(loop.observation().state==2,"first free recording captures immediately");rocker::LoopCommand end;end.kind=2;loop.command(end);loop.beginBlock();loop.process(0,0,true,clock.tick());loop.endBlock();check(loop.observation().frames==4000 && loop.observation().layers==1,"first loop length is the exact integer sample count");
    auto before=loop.observation();for(int i=0;i<4000*20000;++i){if(i%113==0 || i%257==0 || i%1024==0){loop.endBlock();loop.beginBlock();clock.beginBlock();}loop.process(0,0,true,clock.tick());}loop.endBlock();auto after=loop.observation();check(after.cycles-before.cycles==20000 && after.position==before.position,"twenty thousand wraps never lose one sample despite variable blocks");
    rocker::LoopCommand overdub;overdub.kind=3;overdub.delay=37;loop.command(overdub);loop.beginBlock();auto phase=loop.observation().position;for(int i=0;i<4000-phase;++i)loop.process(0,0,true,clock.tick());for(int i=0;i<4000;++i)loop.process(i==137?.25:0,0,true,clock.tick());loop.endBlock();check(loop.observation().layers==2 && buffer.sample(1,100)==.25f,"delayed overdub impulse compensates the reported delay once");
    rocker::LoopCommand undo;undo.kind=6;loop.command(undo);loop.beginBlock();loop.endBlock();check(loop.observation().layers==1 && buffer.sample(0,100)==.5f,"undo removes only the last layer and preserves the first");
    loop.command(overdub);loop.beginBlock();for(int i=0;i<100;++i)loop.process(.3,0,true,clock.tick());loop.joinedStop(5);check(loop.observation().layers==1 && loop.observation().state==6 && buffer.sample(0,100)==.5f,"device loss discards an incomplete overdub and preserves all completed layers");
    rocker::LoopCommand pause;pause.kind=4;loop.command(pause);loop.beginBlock();loop.endBlock();check(loop.observation().state==6 && loop.offlineSample(100,0)==.5,"paused layer permits independent offline export");
    loop.prepare(48000,2);rocker::LoopCommand resume;resume.kind=5;loop.command(resume);loop.beginBlock();loop.endBlock();check(loop.observation().state==6 && loop.observation().rate==8000,"rate change preserves original layers without pretending to resample");
    rocker::LoopCommand clear;clear.kind=7;loop.command(clear);loop.beginBlock();first.aligned=true;first.beats=4;first.countIn=1;loop.command(first);loop.beginBlock();clock.prepare(48000,2);clock.tempo(120);clock.beginBlock();for(int i=0;i<96000;++i)loop.process(.1,.2,true,clock.tick());loop.endBlock();check(loop.observation().state==1,"one-bar count-in excludes all 96000 samples");loop.process(.1,.2,true,clock.tick());loop.endBlock();check(loop.observation().start==96000 && loop.observation().position==1,"aligned first capture starts on the common-clock bar sample");
    loop.joinedStop(5);check(loop.observation().layers==1 && loop.observation().frames==1 && (loop.observation().flags&1),"device loss preserves an explicitly partial first layer");
    {rocker::LoopBuffer small(32);rocker::LooperProcessor bounded;bounded.prepare(8000,1);install.buffer=&small;bounded.command(install);first.aligned=false;first.countIn=0;bounded.command(first);bounded.beginBlock();for(int i=0;i<33;++i)bounded.process(.1,.2,true,{static_cast<uint64_t>(i),0,false,0});bounded.endBlock();check(bounded.observation().frames==32 && bounded.observation().failure==1 && bounded.observation().state==6,"memory limit preserves a partial first layer without writing past capacity");bounded.command(clear);bounded.command(first);bounded.beginBlock();bounded.process(0,0,false,{});bounded.endBlock();check(bounded.observation().layers==0 && bounded.observation().failure==3,"missing guitar input does not invent a silent completed loop");}
    std::cout<<"PASS: "<<checks<<" looper clock, overdub alignment, undo, export and device-loss assertions\n";return 0;
}catch(const std::exception& error){std::cerr<<error.what()<<'\n';return 1;}}
